var r = $json; var b = (r.body!==undefined? r.body : r);
var hist = b.simulated_conversation || b.conversation || [];
var lines = [];
var toolCalls = [];
for (var i=0;i<hist.length;i++){
  var t = hist[i];
  var who = t.role || (t.source) || "?";
  if (t.message) lines.push(who + ": " + t.message);
  // capture tool calls
  var tcs = t.tool_calls || (t.tool_call ? [t.tool_call] : []);
  if (tcs && tcs.length){ for (var j=0;j<tcs.length;j++){ toolCalls.push(tcs[j].tool_name || tcs[j].name || "tool"); } }
}
return [{ json: { status:(r.statusCode!==undefined?r.statusCode:null), turns: lines.length, tool_calls: toolCalls, transcript: lines.join("\n") } }];
